/* ============================================================
   DRIFT LEGENDS — Racing Challenge
   ============================================================ */

:root{
  --bg:#05070c;
  --panel:rgba(12,16,24,.86);
  --panel-2:rgba(18,24,34,.92);
  --line:rgba(255,255,255,.10);
  --txt:#e9eef6;
  --dim:#93a1b5;
  --orange:#ff6a13;
  --orange-2:#ffa53d;
  --cyan:#25d7ff;
  --lime:#9dff4d;
  --red:#ff3b57;
  --grad-fire:linear-gradient(135deg,#ff8a1f 0%,#ff3d2e 55%,#ff1f7a 100%);
  --grad-ice:linear-gradient(135deg,#2ad4ff 0%,#4f7dff 100%);
  --font:"Arial Narrow","Helvetica Neue Condensed",Impact,"Segoe UI",system-ui,sans-serif;
  --ui:"Segoe UI",Roboto,system-ui,-apple-system,sans-serif;
  --safe-t:env(safe-area-inset-top,0px);
  --safe-b:env(safe-area-inset-bottom,0px);
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
}

*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{height:100%}
body{
  margin:0;background:var(--bg);color:var(--txt);
  font-family:var(--ui);overflow:hidden;
  user-select:none;-webkit-user-select:none;touch-action:none;
  overscroll-behavior:none;
}

#game{position:fixed;inset:0;width:100%;height:100%;display:block;background:#05070c;z-index:0}

/* subtle scanline / vignette overlay */
#crt{
  position:fixed;inset:0;pointer-events:none;z-index:1;
  background:
    radial-gradient(120% 90% at 50% 45%,rgba(0,0,0,0) 45%,rgba(0,0,0,.45) 100%),
    repeating-linear-gradient(0deg,rgba(0,0,0,.16) 0 1px,rgba(0,0,0,0) 1px 3px);
  mix-blend-mode:multiply;opacity:.55;
}

.hidden{display:none !important}

/* ================= HUD ================= */
#hud{position:fixed;inset:0;pointer-events:none;z-index:5}
.icon-btn{
  position:absolute;top:calc(10px + var(--safe-t));right:calc(12px + var(--safe-r));
  width:42px;height:42px;border-radius:12px;pointer-events:auto;
  border:1px solid rgba(255,255,255,.18);background:rgba(8,12,20,.62);
  color:#fff;font-size:15px;letter-spacing:1px;cursor:pointer;backdrop-filter:blur(6px);
}
.icon-btn:hover{background:rgba(255,106,19,.85);border-color:#fff}

#countdown{
  position:absolute;left:50%;top:38%;transform:translate(-50%,-50%);
  font-family:var(--font);font-weight:900;font-style:italic;
  font-size:clamp(90px,20vw,220px);line-height:1;letter-spacing:-4px;
  color:#fff;text-shadow:0 0 34px rgba(255,106,19,.9),0 10px 40px rgba(0,0,0,.8);
}
#countdown.go{color:var(--lime);text-shadow:0 0 44px rgba(157,255,77,.9)}

#banner{
  position:absolute;left:50%;top:24%;transform:translate(-50%,-50%) skewX(-8deg);
  font-family:var(--font);font-style:italic;font-weight:900;
  font-size:clamp(26px,5.4vw,54px);letter-spacing:3px;padding:6px 26px;
  background:var(--grad-fire);color:#1a0700;border:2px solid rgba(255,255,255,.7);
  box-shadow:0 12px 40px rgba(0,0,0,.6);white-space:nowrap;
}
#wrongway{
  position:absolute;left:50%;top:15%;transform:translate(-50%,-50%);
  font-family:var(--font);font-weight:900;font-style:italic;letter-spacing:4px;
  font-size:clamp(22px,4.6vw,42px);color:#fff;background:rgba(255,59,87,.92);
  padding:6px 20px;border:2px solid #fff;box-shadow:0 0 30px rgba(255,59,87,.6);
  animation:blink .5s steps(2,end) infinite;
}
@keyframes blink{50%{opacity:.35}}

#driftbox{
  position:absolute;left:50%;bottom:calc(186px + var(--safe-b));transform:translateX(-50%);
  text-align:center;font-family:var(--font);font-style:italic;
  filter:drop-shadow(0 6px 18px rgba(0,0,0,.75));
}
#driftbox b{
  display:block;font-size:clamp(34px,7vw,58px);line-height:.95;font-weight:900;
  color:#fff;text-shadow:0 0 22px rgba(37,215,255,.95);
}
#driftbox span{font-size:13px;letter-spacing:5px;color:var(--cyan);font-weight:700}
#driftbox.pop b{animation:pop .22s ease-out}
@keyframes pop{from{transform:scale(1.28)}to{transform:scale(1)}}

/* ================= TOUCH ================= */
#touch{position:fixed;inset:0;z-index:6;pointer-events:none}
.pad{position:absolute;bottom:calc(14px + var(--safe-b));display:flex;gap:12px;pointer-events:none}
.pad-left{left:calc(14px + var(--safe-l))}
.pad-right{
  right:calc(14px + var(--safe-r));flex-wrap:wrap-reverse;justify-content:flex-end;
  width:min(46vw,300px);
}
.tbtn{
  pointer-events:auto;position:relative;
  width:clamp(70px,17vw,96px);height:clamp(70px,17vw,96px);
  border-radius:20px;border:2px solid rgba(255,255,255,.28);
  background:linear-gradient(180deg,rgba(30,38,52,.72),rgba(10,14,22,.72));
  color:#fff;font-family:var(--font);font-weight:900;font-style:italic;
  font-size:clamp(24px,6vw,32px);cursor:pointer;backdrop-filter:blur(7px);
  box-shadow:0 8px 22px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.16);
  transition:transform .06s ease, background .1s ease, border-color .1s ease;
}
.tbtn.t-small{width:clamp(66px,15vw,86px);height:clamp(52px,12vw,64px);font-size:15px;letter-spacing:1px}
.tbtn.t-nitro{border-color:rgba(37,215,255,.65);color:var(--cyan)}
.tbtn.t-gas{border-color:rgba(157,255,77,.6);color:var(--lime)}
.tbtn.t-brake{border-color:rgba(255,59,87,.6);color:#ff8ea0}
.tbtn.on{transform:scale(.94);background:var(--grad-fire);color:#1a0700;border-color:#fff}
.tbtn.t-nitro.on{background:var(--grad-ice);color:#00131c}
.tbtn.t-gas.on{background:linear-gradient(180deg,#b6ff5d,#39c martial)}
.tbtn.t-gas.on{background:linear-gradient(180deg,#b6ff5d,#2fa13f);color:#062008}
.tbtn.t-brake.on{background:linear-gradient(180deg,#ff7a8c,#c41231);color:#200}

/* ================= SCREENS ================= */
#ui{position:fixed;inset:0;z-index:10;pointer-events:none}
.screen{
  position:absolute;inset:0;display:none;pointer-events:auto;
  padding:calc(18px + var(--safe-t)) calc(18px + var(--safe-r)) calc(18px + var(--safe-b)) calc(18px + var(--safe-l));
  overflow:auto;
}
.screen.active{display:flex;flex-direction:column}
#scr-menu{justify-content:center;align-items:center;
  background:radial-gradient(80% 70% at 50% 40%,rgba(3,6,12,.15) 0%,rgba(3,6,12,.82) 100%)}

.menu-inner{display:flex;flex-direction:column;align-items:center;gap:26px;width:min(760px,100%)}

.logo{text-align:center;line-height:.82}
.logo-kicker{
  font-family:var(--font);letter-spacing:9px;font-size:clamp(10px,1.6vw,14px);
  color:var(--cyan);font-weight:700;margin-bottom:8px;text-shadow:0 0 14px rgba(37,215,255,.7)
}
.logo-drift{
  font-family:var(--font);font-style:italic;font-weight:900;
  font-size:clamp(58px,13vw,132px);letter-spacing:-2px;
  background:linear-gradient(180deg,#fff 8%,#ffd08a 45%,#ff6a13 78%,#ff2d55 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 6px 0 rgba(0,0,0,.55)) drop-shadow(0 0 34px rgba(255,106,19,.55));
}
.logo-legends{
  font-family:var(--font);font-weight:900;font-style:italic;
  font-size:clamp(46px,10.5vw,108px);letter-spacing:10px;
  color:transparent;-webkit-text-stroke:2px rgba(255,255,255,.9);
  text-shadow:0 0 30px rgba(37,215,255,.45);
}
.logo-sub{
  margin-top:12px;font-family:var(--font);letter-spacing:6px;font-size:clamp(11px,2vw,15px);
  color:#ffdca8;font-weight:700;
}

.menu-actions{display:flex;flex-direction:column;gap:12px;width:min(520px,100%)}
.btn-row{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}

.btn{
  font-family:var(--font);font-style:italic;font-weight:900;letter-spacing:2px;
  font-size:16px;text-transform:uppercase;color:#dfe8f5;cursor:pointer;
  padding:13px 22px;border-radius:12px;
  border:1px solid rgba(255,255,255,.18);
  background:linear-gradient(180deg,rgba(28,36,50,.92),rgba(12,16,24,.92));
  box-shadow:0 8px 20px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.10);
  clip-path:polygon(10px 0,100% 0,calc(100% - 10px) 100%,0 100%);
  transition:transform .08s ease, filter .12s ease, background .12s ease;
}
.btn:hover{filter:brightness(1.2);transform:translateY(-1px)}
.btn:active{transform:translateY(1px) scale(.99)}
.btn-primary{background:var(--grad-fire);color:#1c0700;border-color:rgba(255,255,255,.55);text-shadow:0 1px 0 rgba(255,255,255,.25)}
.btn-big{font-size:clamp(22px,4.6vw,30px);padding:18px 30px;letter-spacing:5px}
.btn-ghost{background:rgba(8,11,17,.7);border-color:rgba(255,255,255,.14);color:var(--dim);box-shadow:none}
.btn[disabled]{opacity:.45;cursor:not-allowed;filter:grayscale(.6)}
.btn.wide{width:100%}

.menu-foot{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}
.pill{
  font-family:var(--font);letter-spacing:2px;font-size:13px;font-weight:700;
  padding:7px 14px;border-radius:999px;color:#cfe0f2;
  background:rgba(8,12,20,.7);border:1px solid rgba(255,255,255,.14);
}
.pill b{color:var(--orange-2)}

/* headers */
.head{display:flex;align-items:center;gap:16px;margin-bottom:16px;flex:0 0 auto}
.head h2{
  margin:0;font-family:var(--font);font-style:italic;font-weight:900;
  font-size:clamp(24px,5vw,40px);letter-spacing:4px;flex:1;
  background:linear-gradient(90deg,#fff,#ffb066);-webkit-background-clip:text;background-clip:text;color:transparent;
}
.head .pill{flex:0 0 auto}

/* garage */
.garage{display:grid;grid-template-columns:minmax(190px,250px) 1fr;gap:16px;flex:1 1 auto;min-height:0}
.panel{
  background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:14px;
  box-shadow:0 20px 50px rgba(0,0,0,.55);backdrop-filter:blur(9px);
  clip-path:polygon(0 0,calc(100% - 18px) 0,100% 18px,100% 100%,18px 100%,0 calc(100% - 18px));
}
.list{overflow:auto;display:flex;flex-direction:column;gap:10px}
.car-card{
  display:flex;gap:10px;align-items:center;padding:10px;border-radius:12px;cursor:pointer;
  background:linear-gradient(180deg,rgba(30,38,52,.7),rgba(12,16,24,.7));
  border:1px solid rgba(255,255,255,.10);transition:.14s;
}
.car-card:hover{border-color:rgba(255,255,255,.35);transform:translateX(3px)}
.car-card.active{border-color:var(--orange);box-shadow:0 0 0 1px var(--orange),0 8px 22px rgba(255,106,19,.28)}
.car-card.locked{opacity:.72}
.car-card canvas{width:74px;height:40px;flex:0 0 auto;background:rgba(0,0,0,.3);border-radius:8px}
.car-card .cc{flex:1;min-width:0}
.car-card .cc b{display:block;font-family:var(--font);font-style:italic;letter-spacing:1.5px;font-size:15px}
.car-card .cc span{font-size:11px;letter-spacing:2px;color:var(--dim);text-transform:uppercase}
.car-card .price{font-family:var(--font);font-size:13px;color:var(--orange-2);letter-spacing:1px}
.car-card .owned{font-size:11px;color:var(--lime);letter-spacing:1px;font-weight:700}
.car-card .equipped{font-size:10px;background:var(--grad-fire);color:#1c0700;padding:2px 7px;border-radius:6px;font-weight:900;letter-spacing:1px}

.detail{overflow:auto;display:flex;flex-direction:column;gap:10px}
#car-preview{width:100%;height:auto;max-height:220px;background:
  radial-gradient(70% 90% at 50% 30%,rgba(255,255,255,.07),rgba(0,0,0,.35));
  border-radius:12px;border:1px solid rgba(255,255,255,.08)}
.detail-head{display:flex;align-items:baseline;gap:12px}
.detail-head h3{margin:0;font-family:var(--font);font-style:italic;font-size:clamp(22px,4vw,32px);letter-spacing:2px}
.tag{font-size:11px;letter-spacing:3px;padding:4px 10px;border-radius:6px;background:var(--grad-ice);color:#00131c;font-weight:900}
.detail p{margin:0;color:var(--dim);font-size:14px;line-height:1.5}

.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 16px}
.stat{display:flex;flex-direction:column;gap:4px}
.stat span{font-size:11px;letter-spacing:2.4px;color:var(--dim)}
.bar{height:9px;border-radius:5px;background:rgba(255,255,255,.10);overflow:hidden}
.bar i{display:block;height:100%;border-radius:5px;background:linear-gradient(90deg,var(--cyan),var(--orange));transition:width .3s ease}

.upg-head{display:flex;justify-content:space-between;font-size:11px;letter-spacing:3px;color:var(--dim);margin-top:4px}
.upgrades{display:flex;flex-direction:column;gap:8px}
.upg{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:10px;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.07)}
.upg .u-name{width:88px;font-family:var(--font);font-style:italic;letter-spacing:1.5px;font-size:14px}
.pips{display:flex;gap:4px;flex:1}
.pip{width:16px;height:9px;border-radius:3px;background:rgba(255,255,255,.14)}
.pip.on{background:linear-gradient(90deg,var(--orange),var(--orange-2));box-shadow:0 0 8px rgba(255,106,19,.7)}
.upg button{
  font-family:var(--font);font-weight:900;font-style:italic;font-size:12px;letter-spacing:1px;
  padding:7px 11px;border-radius:8px;cursor:pointer;color:#1c0700;border:0;
  background:linear-gradient(180deg,#ffd08a,#ff8a1f);
}
.upg button:hover{filter:brightness(1.12)}
.upg button[disabled]{background:rgba(255,255,255,.12);color:var(--dim);cursor:not-allowed}

/* tracks */
.track-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;flex:1 1 auto;min-height:0;overflow:auto;padding-bottom:6px}
.track-card{
  position:relative;display:flex;flex-direction:column;gap:8px;padding:14px;
  background:var(--panel);border:1px solid var(--line);border-radius:16px;cursor:pointer;
  clip-path:polygon(0 0,calc(100% - 18px) 0,100% 18px,100% 100%,18px 100%,0 calc(100% - 18px));
  transition:.15s;overflow:hidden;
}
.track-card:hover{transform:translateY(-4px);border-color:rgba(255,255,255,.4)}
.track-card.active{border-color:var(--orange);box-shadow:0 0 0 1px var(--orange),0 18px 40px rgba(255,106,19,.25)}
.track-card canvas{width:100%;height:150px;background:rgba(0,0,0,.4);border-radius:10px}
.track-card h3{margin:0;font-family:var(--font);font-style:italic;letter-spacing:2px;font-size:20px}
.track-card p{margin:0;font-size:12.5px;color:var(--dim);line-height:1.45}
.tc-meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.stars{letter-spacing:2px;color:var(--orange-2);font-size:13px}
.tc-meta .pill{font-size:11px;padding:5px 10px}
.track-card .badge{
  position:absolute;top:0;right:0;font-size:10px;letter-spacing:2px;font-weight:900;
  background:var(--grad-fire);color:#1c0700;padding:5px 12px;border-bottom-left-radius:10px;
}
.track-foot{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding-top:14px;flex:0 0 auto}
.laps{display:flex;gap:8px;align-items:center;font-family:var(--font);letter-spacing:3px;font-size:14px;color:var(--dim)}
.chip{
  width:44px;height:38px;border-radius:10px;cursor:pointer;font-family:var(--font);
  font-weight:900;font-size:17px;color:#cfe0f2;border:1px solid rgba(255,255,255,.16);
  background:rgba(14,18,27,.9);
}
.chip.active{background:var(--grad-fire);color:#1c0700;border-color:#fff}

/* help */
.help{flex:1 1 auto;overflow:auto}
.help-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}
.help-col h4{margin:0 0 10px;font-family:var(--font);letter-spacing:4px;color:var(--orange-2);font-size:15px}
.help-col ul{margin:0;padding-left:16px;line-height:2;font-size:14px;color:#cdd8e6}
kbd{
  display:inline-block;min-width:24px;text-align:center;padding:2px 7px;margin-right:4px;
  border-radius:6px;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.22);
  border-bottom-width:2px;font-family:var(--ui);font-size:11.5px;font-weight:700;color:#fff;
}
.help-foot{display:flex;gap:10px;margin-top:18px;flex-wrap:wrap}

/* cards (pause / results) */
#scr-pause,#scr-results{align-items:center;justify-content:center;background:rgba(3,6,12,.78);backdrop-filter:blur(7px)}
.card{
  width:min(620px,100%);max-height:100%;overflow:auto;padding:26px;border-radius:20px;
  background:linear-gradient(180deg,rgba(17,22,32,.97),rgba(8,11,17,.97));
  border:1px solid rgba(255,255,255,.16);
  box-shadow:0 40px 90px rgba(0,0,0,.7);
  display:flex;flex-direction:column;gap:12px;
  clip-path:polygon(0 0,calc(100% - 26px) 0,100% 26px,100% 100%,26px 100%,0 calc(100% - 26px));
}
.card h2{
  margin:0 0 6px;text-align:center;font-family:var(--font);font-style:italic;font-weight:900;
  font-size:clamp(30px,7vw,52px);letter-spacing:6px;
  background:linear-gradient(90deg,#fff,#ff9a4a);-webkit-background-clip:text;background-clip:text;color:transparent;
}
.pause-stats{display:flex;justify-content:center;gap:16px;color:var(--dim);font-size:13px;letter-spacing:2px;margin-bottom:6px}

.res-top{display:flex;align-items:center;gap:18px;justify-content:center}
.res-pos{
  font-family:var(--font);font-style:italic;font-weight:900;font-size:clamp(50px,13vw,92px);line-height:.9;
  background:var(--grad-fire);-webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 6px 20px rgba(255,106,19,.5));
}
.res-title{text-align:left}
.res-title h2{font-size:clamp(24px,5vw,38px);text-align:left}
.res-title span{font-size:12px;letter-spacing:4px;color:var(--dim)}
.res-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;text-align:center}
.res-grid div{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:10px 4px}
.res-grid span{display:block;font-size:10px;letter-spacing:2.5px;color:var(--dim);margin-bottom:5px}
.res-grid b{font-family:var(--font);font-size:clamp(14px,3vw,19px);letter-spacing:1px;color:#fff}
.res-table-wrap{max-height:230px;overflow:auto;border-radius:12px;border:1px solid rgba(255,255,255,.08)}
.res-table{width:100%;border-collapse:collapse;font-size:13.5px}
.res-table th{position:sticky;top:0;background:rgba(10,14,22,.98);font-size:10.5px;letter-spacing:2.5px;color:var(--dim);text-align:left;padding:9px 10px}
.res-table td{padding:8px 10px;border-top:1px solid rgba(255,255,255,.06);color:#d6e0ee}
.res-table tr.me td{background:rgba(255,106,19,.14);color:#fff;font-weight:700}
.res-table td.pos{font-family:var(--font);font-style:italic;font-weight:900;color:var(--orange-2);width:52px}
.res-actions{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin-top:4px}

/* loading + noscript */
#loading{
  position:fixed;inset:0;z-index:50;display:flex;flex-direction:column;gap:16px;
  align-items:center;justify-content:center;background:#05070c;
  font-family:var(--font);letter-spacing:6px;font-size:13px;color:var(--dim);
}
#loading.done{opacity:0;pointer-events:none;transition:opacity .5s ease .12s}
.loader-bar{width:min(320px,60vw);height:6px;border-radius:4px;background:rgba(255,255,255,.12);overflow:hidden}
.loader-bar i{display:block;height:100%;width:40%;background:var(--grad-fire);animation:slide 1s ease-in-out infinite}
@keyframes slide{0%{transform:translateX(-110%)}100%{transform:translateX(260%)}}
.noscript{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:#05070c;color:#fff;z-index:99}

/* ================= responsive ================= */
@media (max-width:860px){
  .garage{grid-template-columns:1fr;gap:12px}
  .list{flex-direction:row;overflow-x:auto;overflow-y:hidden;flex:0 0 auto}
  .car-card{flex:0 0 auto;width:210px}
  .detail{max-height:none}
  .stats{grid-template-columns:1fr}
  .res-grid{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:560px){
  .btn-row{gap:8px}
  .btn{font-size:14px;padding:11px 16px;letter-spacing:1.5px}
  .head h2{letter-spacing:2px}
  .help-col ul{line-height:1.85;font-size:13px}
}
@media (max-height:520px){
  .logo-drift{font-size:clamp(44px,12vh,80px)}
  .logo-legends{font-size:clamp(36px,10vh,66px)}
  #driftbox{bottom:calc(150px + var(--safe-b))}
}

