/* ============================================================
   Procedural sprites: car bodies, wheels, soft glow blobs.
   Everything is pre-rendered once and blitted per frame.
   ============================================================ */

import { PHYS } from './config.js';
import { TAU, mulberry32 } from './utils.js';

const S = 2;                       // sprite supersampling
const HL = PHYS.carLength / 2;      // half length  (24)
const HW = PHYS.carWidth / 2;       // half width   (13)

const blobCache = new Map();
const glowCache = new Map();

export function blobSprite(color) {
  if (blobCache.has(color)) return blobCache.get(color);
  const size = 72;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const x = c.getContext('2d');
  const g = x.createRadialGradient(size / 2, size / 2, 1, size / 2, size / 2, size / 2);
  g.addColorStop(0, color);
  g.addColorStop(0.45, color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = g;
  x.fillRect(0, 0, size, size);
  blobCache.set(color, c);
  return c;
}

export function glowSprite(color) {
  if (glowCache.has(color)) return glowCache.get(color);
  const size = 128;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const x = c.getContext('2d');
  const g = x.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, color);
  g.addColorStop(0.3, color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = g;
  x.fillRect(0, 0, size, size);
  glowCache.set(color, c);
  return c;
}

function roundRect(x, px, py, w, h, r) {
  const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  x.beginPath();
  x.moveTo(px + rr, py);
  x.arcTo(px + w, py, px + w, py + h, rr);
  x.arcTo(px + w, py + h, px, py + h, rr);
  x.arcTo(px, py + h, px, py, rr);
  x.arcTo(px, py, px + w, py, rr);
  x.closePath();
}

/* body silhouette, forward = +x */
function outline(shape) {
  const p = new Path2D();
  if (shape === 'muscle') {
    p.moveTo(HL, -HW * 0.72);
    p.quadraticCurveTo(HL + 1, -HW, HL - 7, -HW);
    p.lineTo(-HL + 6, -HW * 1.02);
    p.quadraticCurveTo(-HL - 1, -HW * .98, -HL - 1, -HW * .66);
    p.lineTo(-HL - 1, HW * .66);
    p.quadraticCurveTo(-HL - 1, HW * .98, -HL + 6, HW * 1.02);
    p.lineTo(HL - 7, HW);
    p.quadraticCurveTo(HL + 1, HW, HL, HW * 0.72);
    p.closePath();
  } else if (shape === 'hyper') {
    p.moveTo(HL + 2, -HW * 0.40);
    p.quadraticCurveTo(HL + 3, -HW * 0.86, HL - 9, -HW);
    p.lineTo(-HL + 5, -HW * 1.0);
    p.quadraticCurveTo(-HL - 4, -HW * .86, -HL - 5, -HW * .3);
    p.lineTo(-HL - 5, HW * .3);
    p.quadraticCurveTo(-HL - 4, HW * .86, -HL + 5, HW);
    p.lineTo(HL - 9, HW);
    p.quadraticCurveTo(HL + 3, HW * 0.86, HL + 2, HW * 0.40);
    p.closePath();
  } else if (shape === 'rally') {
    p.moveTo(HL - 1, -HW * 0.82);
    p.quadraticCurveTo(HL + 2, -HW, HL - 6, -HW * 1.04);
    p.lineTo(-HL + 4, -HW * 1.06);
    p.quadraticCurveTo(-HL - 3, -HW * 1.02, -HL - 3, -HW * .6);
    p.lineTo(-HL - 3, HW * .6);
    p.quadraticCurveTo(-HL - 3, HW * 1.02, -HL + 4, HW * 1.06);
    p.lineTo(HL - 6, HW * 1.04);
    p.quadraticCurveTo(HL + 2, HW, HL - 1, HW * 0.82);
    p.closePath();
  } else {                       // coupe / drift
    p.moveTo(HL, -HW * 0.52);
    p.quadraticCurveTo(HL + 1.5, -HW * .9, HL - 7, -HW * .99);
    p.quadraticCurveTo(HL - 15, -HW, -HL + 4, -HW * .96);
    p.quadraticCurveTo(-HL - 3, -HW * .9, -HL - 3, -HW * .35);
    p.lineTo(-HL - 3, HW * .35);
    p.quadraticCurveTo(-HL - 3, HW * .9, -HL + 4, HW * .96);
    p.quadraticCurveTo(HL - 15, HW, HL - 7, HW * .99);
    p.quadraticCurveTo(HL + 1.5, HW * .9, HL, HW * 0.52);
    p.closePath();
  }
  return p;
}

/**
 * Pre-render a car body (no wheels) into an off-screen canvas.
 */
export function makeCarSprite(shape, colors, glass, seed = 1) {
  const w = Math.ceil((PHYS.carLength + 30) * S);
  const h = Math.ceil((PHYS.carWidth + 26) * S);
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const x = c.getContext('2d');
  x.translate(w / 2, h / 2);
  x.scale(S, S);

  const body = outline(shape);
  const rng = mulberry32(seed * 977 + 13);

  // ---- main paint (light falls from the top-left)
  const grad = x.createLinearGradient(0, -HW, 0, HW);
  grad.addColorStop(0, colors.body);
  grad.addColorStop(0.42, colors.body);
  grad.addColorStop(1, colors.body2);
  x.fillStyle = grad;
  x.fill(body);

  // clip everything that follows to the silhouette
  x.save();
  x.clip(body);

  // ---- width-wise shading
  const shade = x.createLinearGradient(-HL, 0, HL, 0);
  shade.addColorStop(0, 'rgba(0,0,0,.35)');
  shade.addColorStop(0.35, 'rgba(0,0,0,0)');
  shade.addColorStop(0.75, 'rgba(255,255,255,.10)');
  shade.addColorStop(1, 'rgba(0,0,0,.30)');
  x.fillStyle = shade;
  x.fillRect(-HL - 6, -HW - 4, HL * 2 + 12, HW * 2 + 8);

  // ---- racing stripes
  if (shape !== 'hyper') {
    x.globalAlpha = .92;
    x.fillStyle = colors.accent;
    x.fillRect(-HL, -6.5, HL * 2, 3.4);
    x.fillRect(-HL, 3.1, HL * 2, 3.4);
    x.globalAlpha = 1;
  } else {
    x.globalAlpha = .8;
    x.fillStyle = colors.accent;
    x.fillRect(-HL, -2, HL * 2, 4);
    x.globalAlpha = 1;
  }

  // ---- glass house
  const glassGrad = x.createLinearGradient(0, -HW, 0, HW);
  glassGrad.addColorStop(0, '#9fd6ff');
  glassGrad.addColorStop(0.25, glass);
  glassGrad.addColorStop(1, '#050a10');
  x.fillStyle = glassGrad;
  if (shape === 'rally') {
    roundRect(x, -11, -HW + 4, 22, HW * 2 - 8, 5);
  } else if (shape === 'muscle') {
    roundRect(x, -12, -HW + 4.5, 24, HW * 2 - 9, 4);
  } else if (shape === 'hyper') {
    roundRect(x, -10, -HW + 4.5, 21, HW * 2 - 9, 6);
  } else {
    roundRect(x, -11, -HW + 4, 21, HW * 2 - 8, 6);
  }
  x.fill();
  // windscreen / rear screen split
  x.fillStyle = 'rgba(0,0,0,.55)';
  x.fillRect(-3.4, -HW + 4, 2.2, HW * 2 - 8);
  x.fillRect(5.4, -HW + 4, 1.6, HW * 2 - 8);
  // roof panel
  x.fillStyle = colors.body2;
  roundRect(x, -1.4, -HW + 5.5, 6.4, HW * 2 - 11, 3);
  x.fill();

  // ---- panel lines
  x.strokeStyle = 'rgba(0,0,0,.32)';
  x.lineWidth = 1;
  x.beginPath();
  x.moveTo(HL - 6, -HW * .9); x.lineTo(HL - 6, HW * .9);
  x.moveTo(-HL + 5, -HW * .9); x.lineTo(-HL + 5, HW * .9);
  x.stroke();

  // ---- vents / details per shape
  if (shape === 'muscle') {
    x.fillStyle = 'rgba(0,0,0,.55)';
    roundRect(x, HL - 13, -6, 8, 12, 2);
    x.fill();
    x.fillStyle = 'rgba(255,255,255,.16)';
    roundRect(x, HL - 13, -6, 8, 3, 2);
    x.fill();
  }
  if (shape === 'drift') {
    x.fillStyle = 'rgba(0,0,0,.5)';
    for (let i = 0; i < 3; i++) {
      x.fillRect(HL - 14 + i * 4, -HW + 3, 2, HW * 2 - 6);
    }
  }
  if (shape === 'rally') {
    x.fillStyle = '#1b2230';
    roundRect(x, -9, -HW + 1.5, 18, 3, 1.5);
    x.fill();
    x.fillStyle = colors.accent;
    for (let i = 0; i < 4; i++) x.fillRect(-8 + i * 4.6, -HW + 1.9, 3, 2.2);
  }

  // ---- highlights
  x.globalAlpha = .5;
  x.fillStyle = '#fff';
  x.fillRect(-HL + 3, -HW + 2.2, HL * 2 - 6, 2);
  x.globalAlpha = 1;

  // ---- dirt / spec speckle for texture
  x.globalAlpha = .07;
  for (let i = 0; i < 70; i++) {
    x.fillStyle = rng() > .5 ? '#fff' : '#000';
    x.fillRect(-HL + rng() * HL * 2, -HW + rng() * HW * 2, 1.6, 1.6);
  }
  x.globalAlpha = 1;

  x.restore();   // end clip

  // ---- spoiler
  if (shape === 'drift' || shape === 'hyper' || shape === 'muscle') {
    const wingW = shape === 'hyper' ? HW + 3.5 : HW + 2.5;
    x.fillStyle = 'rgba(0,0,0,.78)';
    roundRect(x, -HL - 1, -wingW, 4.5, wingW * 2, 2);
    x.fill();
    x.fillStyle = 'rgba(255,255,255,.18)';
    x.fillRect(-HL - 1, -wingW, 4.5, 2);
    x.fillStyle = '#0b0d11';
    x.fillRect(-HL + 3, -wingW + 1.5, 3, 3);
    x.fillRect(-HL + 3, wingW - 4.5, 3, 3);
  }

  // ---- lights
  x.fillStyle = '#fff8d6';
  roundRect(x, HL - 4.5, -HW * .82, 4, 5, 1.5); x.fill();
  roundRect(x, HL - 4.5, HW * .82 - 5, 4, 5, 1.5); x.fill();
  x.fillStyle = '#ff4a5e';
  roundRect(x, -HL + 1, -HW * .85, 3.4, 5.4, 1.4); x.fill();
  roundRect(x, -HL + 1, HW * .85 - 5.4, 3.4, 5.4, 1.4); x.fill();

  // ---- mirrors
  x.fillStyle = colors.body2;
  roundRect(x, 4, -HW - 3, 5, 4, 1.5); x.fill();
  roundRect(x, 4, HW - 1, 5, 4, 1.5); x.fill();

  // ---- outline
  x.strokeStyle = 'rgba(0,0,0,.62)';
  x.lineWidth = 1.4;
  x.stroke(outline(shape));

  return { canvas: c, w: w / S, h: h / S };
}

export function drawWheel(ctx, cx, cy, ang, steer, front) {
  const w = front ? 11 : 12;
  const h = 7.2;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(steer);
  ctx.fillStyle = '#0a0c10';
  roundRect(ctx, -w / 2, -h / 2, w, h, 2.4);
  ctx.fill();
  ctx.fillStyle = '#2a2f38';
  roundRect(ctx, -w / 2 + 2, -h / 2 + 1.5, w - 4, h - 3, 1.4);
  ctx.fill();
  ctx.fillStyle = front ? '#4b525e' : '#3a4049';
  roundRect(ctx, -w / 2 + 3.4, -h / 2 + 2.3, w - 6.8, h - 4.6, 1);
  ctx.fill();
  ctx.restore();
}

/** Pre-rendered drop shadow ellipse used beneath every car. */
export function makeShadowSprite() {
  const w = 132, h = 96;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const x = c.getContext('2d');
  x.translate(w / 2, h / 2);
  x.scale(1.7, 1.7);
  const g = x.createRadialGradient(0, 2, 2, 0, 2, 34);
  g.addColorStop(0, 'rgba(0,0,0,.55)');
  g.addColorStop(0.55, 'rgba(0,0,0,.34)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = g;
  x.beginPath();
  x.ellipse(0, 2, 34, 24, 0, 0, TAU);
  x.fill();
  return c;
}

/* ============================================================
   Particle / skid-mark / floating-text pool + camera shake.
   All pools are pre-allocated so nothing allocates during play.
   ============================================================ */

import { blobSprite } from './sprites.js';
import { TAU, clamp } from './utils.js';

const MAX_PARTS = 640;
const MAX_SKIDS = 1400;
const MAX_TEXTS = 40;

function newPart() {
  return { on: false, kind: 0, x: 0, y: 0, vx: 0, vy: 0, age: 0, life: 1, size: 10, size1: 20, color: '#fff', a0: 1, drag: 1, grav: 0, rot: 0, spin: 0, w: 3 };
}

class Effects {
  constructor() {
    this.parts = new Array(MAX_PARTS);
    for (let i = 0; i < MAX_PARTS; i++) this.parts[i] = newPart();
    this.head = 0;
    this.skids = new Array(MAX_SKIDS);
    for (let i = 0; i < MAX_SKIDS; i++) this.skids[i] = { on: false, x1: 0, y1: 0, x2: 0, y2: 0, w: 4, a: 0, age: 0, life: 8, dark: 1 };
    this.shead = 0;
    this.texts = new Array(MAX_TEXTS);
    for (let i = 0; i < MAX_TEXTS; i++) this.texts[i] = { on: false, x: 0, y: 0, vy: -34, str: '', color: '#fff', size: 26, age: 0, life: 1.2, crit: false };
    this.theads = 0;
    this.shakeAmt = 0;
    this.shakeT = 0;
    this.quality = 1;
    this.flash = 0;
    this.flashColor = 'rgba(255,255,255,.5)';
  }

  reset() {
    for (const p of this.parts) p.on = false;
    for (const s of this.skids) s.on = false;
    for (const t of this.texts) t.on = false;
    this.shakeAmt = 0;
    this.flash = 0;
  }

  spawn(kind, x, y, o) {
    let p = null;
    for (let i = 0; i < MAX_PARTS; i++) {
      const c = this.parts[(this.head + i) % MAX_PARTS];
      if (!c.on) { p = c; this.head = (this.head + i + 1) % MAX_PARTS; break; }
    }
    if (!p) { p = this.parts[this.head]; this.head = (this.head + 1) % MAX_PARTS; }
    p.on = true;
    p.kind = kind;
    p.x = x; p.y = y;
    p.vx = o.vx || 0; p.vy = o.vy || 0;
    p.age = 0;
    p.life = o.life || 1;
    p.size = o.size || 10;
    p.size1 = o.size1 !== undefined ? o.size1 : p.size * 1.8;
    p.color = o.color || '#fff';
    p.a0 = o.a0 !== undefined ? o.a0 : 1;
    p.drag = o.drag !== undefined ? o.drag : 1.4;
    p.grav = o.grav || 0;
    p.rot = o.rot || 0;
    p.spin = o.spin || 0;
    p.w = o.w || 3;
    return p;
  }

  smoke(x, y, vx, vy, amount, color = '#e8edf6', scale = 1) {
    const n = Math.max(1, Math.round(amount * this.quality));
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      const sp = 10 + Math.random() * 40;
      this.spawn(0, x, y, {
        vx: vx * .35 + Math.cos(a) * sp,
        vy: vy * .35 + Math.sin(a) * sp,
        life: .7 + Math.random() * .8,
        size: (12 + Math.random() * 10) * scale,
        size1: (46 + Math.random() * 34) * scale,
        color, a0: .34 + Math.random() * .22,
        drag: 1.9,
      });
    }
  }

  dust(x, y, vx, vy, amount, color = '#c9a86a') {
    const n = Math.max(1, Math.round(amount * this.quality));
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      const sp = 16 + Math.random() * 70;
      this.spawn(0, x, y, {
        vx: vx * .4 + Math.cos(a) * sp,
        vy: vy * .4 + Math.sin(a) * sp,
        life: .5 + Math.random() * .6,
        size: 9 + Math.random() * 8,
        size1: 34 + Math.random() * 26,
        color, a0: .5 + Math.random() * .3,
        drag: 2.4,
      });
    }
  }

  spark(x, y, vx, vy, amount, color = '#ffd36b') {
    const n = Math.max(1, Math.round(amount * this.quality));
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      const sp = 60 + Math.random() * 240;
      this.spawn(1, x, y, {
        vx: vx * .5 + Math.cos(a) * sp,
        vy: vy * .5 + Math.sin(a) * sp,
        life: .22 + Math.random() * .4,
        size: 3, size1: 1,
        color, a0: 1, drag: 3.2, grav: 90, w: 1.6 + Math.random() * 1.8,
      });
    }
  }

  flame(x, y, vx, vy, color = '#7cdcff') {
    this.spawn(0, x, y, {
      vx, vy, life: .18 + Math.random() * .2,
      size: 12 + Math.random() * 8, size1: 3,
      color, a0: .85, drag: 5,
    });
  }

  debris(x, y, amount, color = '#cfd6e2') {
    const n = Math.max(1, Math.round(amount * this.quality));
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      const sp = 60 + Math.random() * 220;
      this.spawn(2, x, y, {
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: .6 + Math.random() * .7,
        size: 3 + Math.random() * 4, size1: 3,
        color, a0: 1, drag: 2.2, grav: 140,
        rot: Math.random() * TAU, spin: (Math.random() - .5) * 18,
      });
    }
  }

  skid(x1, y1, x2, y2, a, w = 5, dark = 1) {
    const s = this.skids[this.shead];
    this.shead = (this.shead + 1) % MAX_SKIDS;
    s.on = true;
    s.x1 = x1; s.y1 = y1; s.x2 = x2; s.y2 = y2;
    s.a = clamp(a, 0, .85);
    s.w = w;
    s.age = 0;
    s.life = 7;
    s.dark = dark;
  }

  text(x, y, str, color = '#fff', size = 26, life = 1.2) {
    const t = this.texts[this.theads];
    this.theads = (this.theads + 1) % MAX_TEXTS;
    t.on = true;
    t.x = x; t.y = y; t.str = str; t.color = color; t.size = size;
    t.age = 0; t.life = life; t.vy = -46;
  }

  addShake(v) { this.shakeAmt = Math.min(26, this.shakeAmt + v); }

  update(dt) {
    for (const p of this.parts) {
      if (!p.on) continue;
      p.age += dt;
      if (p.age >= p.life) { p.on = false; continue; }
      const d = Math.exp(-p.drag * dt);
      p.vx *= d;
      p.vy = p.vy * d + p.grav * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.spin * dt;
    }
    for (const s of this.skids) {
      if (!s.on) continue;
      s.age += dt;
      if (s.age >= s.life) s.on = false;
    }
    for (const t of this.texts) {
      if (!t.on) continue;
      t.age += dt;
      if (t.age >= t.life) { t.on = false; continue; }
      t.y += t.vy * dt;
      t.vy *= Math.exp(-1.4 * dt);
    }
    this.shakeAmt *= Math.exp(-5.5 * dt);
    if (this.shakeAmt < .05) this.shakeAmt = 0;
    this.shakeT += dt;
    if (this.flash > 0) this.flash = Math.max(0, this.flash - dt * 3);
  }

  shakeOffset() {
    if (!this.shakeAmt) return [0, 0];
    const t = this.shakeT * 47;
    return [
      Math.sin(t * 1.7) * this.shakeAmt,
      Math.cos(t * 2.3) * this.shakeAmt * .8,
    ];
  }

  /** skid marks + soft blobs (called inside the world transform) */
  drawUnder(ctx) {
    // --- skid marks, batched into 6 alpha buckets
    const buckets = [[], [], [], [], [], []];
    for (const s of this.skids) {
      if (!s.on) continue;
      const k = 1 - s.age / s.life;
      const bi = clamp(Math.floor(k * 6), 0, 5);
      buckets[bi].push(s);
    }
    ctx.lineCap = 'round';
    for (let b = 0; b < 6; b++) {
      const list = buckets[b];
      if (!list.length) continue;
      ctx.globalAlpha = (b + 1) / 6 * .78;
      for (const dark of [1, 0]) {
        let started = false;
        ctx.beginPath();
        for (const s of list) {
          if ((s.dark ? 1 : 0) !== dark) continue;
          if (!started) { started = true; } else { /* continued */ }
          ctx.moveTo(s.x1, s.y1);
          ctx.lineTo(s.x2, s.y2);
        }
        if (started) {
          ctx.strokeStyle = dark ? '#12151b' : 'rgba(255,255,255,.75)';
          ctx.lineWidth = 5;
          ctx.stroke();
        }
      }
    }
    ctx.globalAlpha = 1;
  }

  drawParticles(ctx) {
    // soft blobs first
    ctx.globalCompositeOperation = 'source-over';
    for (const p of this.parts) {
      if (!p.on || p.kind !== 0) continue;
      const t = p.age / p.life;
      const size = p.size + (p.size1 - p.size) * t;
      ctx.globalAlpha = p.a0 * (1 - t) * (1 - t * .35);
      const img = blobSprite(p.color);
      ctx.drawImage(img, p.x - size / 2, p.y - size / 2, size, size);
    }
    ctx.globalAlpha = 1;

    // debris (opaque)
    for (const p of this.parts) {
      if (!p.on || p.kind !== 2) continue;
      const t = p.age / p.life;
      ctx.globalAlpha = 1 - t;
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rot);
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.size, -p.size * .6, p.size * 2, p.size * 1.2);
      ctx.restore();
    }
    ctx.globalAlpha = 1;

    // sparks / flames additively
    ctx.globalCompositeOperation = 'lighter';
    for (const p of this.parts) {
      if (!p.on || p.kind !== 1) continue;
      const t = p.age / p.life;
      ctx.globalAlpha = 1 - t;
      ctx.strokeStyle = p.color;
      ctx.lineWidth = p.w;
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
      ctx.lineTo(p.x - p.vx * .02, p.y - p.vy * .02);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
  }

  drawTexts(ctx) {
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (const t of this.texts) {
      if (!t.on) continue;
      const k = t.age / t.life;
      const a = k < .12 ? k / .12 : 1 - Math.max(0, (k - .55) / .45);
      ctx.globalAlpha = clamp(a, 0, 1);
      const sc = 1 + (k < .18 ? (0.18 - k) * 2.4 : 0);
      ctx.save();
      ctx.translate(t.x, t.y);
      ctx.scale(sc, sc);
      ctx.font = `900 italic ${t.size}px "Arial Narrow", Impact, sans-serif`;
      ctx.lineWidth = Math.max(3, t.size * .16);
      ctx.strokeStyle = 'rgba(0,0,0,.75)';
      ctx.strokeText(t.str, 0, 0);
      ctx.fillStyle = t.color;
      ctx.fillText(t.str, 0, 0);
      ctx.restore();
    }
    ctx.globalAlpha = 1;
  }
}

export const effects = new Effects();

/* ============================================================
   WebAudio sound: synthesised engine, tyre squeal, nitro and
   one-shot cues. No external audio files required.
   ============================================================ */

class AudioEngine {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.ok = false;
    this.started = false;
    this.noiseBuf = null;
    this.engineGain = null;
    this.skidGain = null;
    this.boostGain = null;
    this.filter = null;
    this.osc1 = null;
    this.osc2 = null;
    this.master = null;
    this._skidSrc = null;
    this._boostSrc = null;
  }

  init() {
    if (this.ctx) return;
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      const ctx = new AC();
      this.ctx = ctx;

      this.master = ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.85;
      this.master.connect(ctx.destination);

      // --- noise buffer (shared)
      const len = ctx.sampleRate * 2;
      const buf = ctx.createBuffer(1, len, ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      this.noiseBuf = buf;

      // --- engine: two oscillators -> lowpass
      this.filter = ctx.createBiquadFilter();
      this.filter.type = 'lowpass';
      this.filter.frequency.value = 400;
      this.filter.Q.value = 7;

      this.engineGain = ctx.createGain();
      this.engineGain.gain.value = 0;

      this.osc1 = ctx.createOscillator();
      this.osc1.type = 'sawtooth';
      this.osc1.frequency.value = 60;
      this.osc2 = ctx.createOscillator();
      this.osc2.type = 'square';
      this.osc2.frequency.value = 30;
      const g2 = ctx.createGain();
      g2.gain.value = .5;
      this.osc1.connect(this.filter);
      this.osc2.connect(g2);
      g2.connect(this.filter);
      this.filter.connect(this.engineGain);
      this.engineGain.connect(this.master);
      this.osc1.start();
      this.osc2.start();

      // --- tyre squeal
      const skidSrc = ctx.createBufferSource();
      skidSrc.buffer = buf;
      skidSrc.loop = true;
      const bp = ctx.createBiquadFilter();
      bp.type = 'bandpass';
      bp.frequency.value = 1700;
      bp.Q.value = 1.6;
      this.skidGain = ctx.createGain();
      this.skidGain.gain.value = 0;
      skidSrc.connect(bp);
      bp.connect(this.skidGain);
      this.skidGain.connect(this.master);
      skidSrc.start();
      this._skidSrc = skidSrc;
      this._skidFilter = bp;

      // --- nitro hiss
      const boostSrc = ctx.createBufferSource();
      boostSrc.buffer = buf;
      boostSrc.loop = true;
      const hp = ctx.createBiquadFilter();
      hp.type = 'highpass';
      hp.frequency.value = 900;
      this.boostGain = ctx.createGain();
      this.boostGain.gain.value = 0;
      boostSrc.connect(hp);
      hp.connect(this.boostGain);
      this.boostGain.connect(this.master);
      boostSrc.start();
      this._boostSrc = boostSrc;

      this.ok = true;
    } catch (e) {
      this.ok = false;
    }
  }

  resume() {
    if (!this.ctx) this.init();
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
  }

  setMuted(m) {
    this.muted = m;
    try {
      if (this.master) this.master.gain.value = m ? 0 : 0.85;
    } catch (e) { /* ignore */ }
  }

  /** continuous mix, called once per rendered frame */
  mix(s) {
    if (!this.ok || !this.ctx) return;
    const t = this.ctx.currentTime;
    const r = Math.min(1, s.speed / 620);
    try {
      this.osc1.frequency.setTargetAtTime(52 + r * 168 + s.throttle * 22, t, .05);
      this.osc2.frequency.setTargetAtTime((52 + r * 168) * .5, t, .05);
      this.filter.frequency.setTargetAtTime(340 + r * 2400 + (s.boost ? 900 : 0), t, .06);
      this.engineGain.gain.setTargetAtTime(s.active ? .055 + s.throttle * .055 + r * .03 : 0, t, .08);
      this.skidGain.gain.setTargetAtTime(s.active ? s.skid * .09 : 0, t, .05);
      if (this._skidFilter) this._skidFilter.frequency.setTargetAtTime(1300 + r * 1400, t, .08);
      this.boostGain.gain.setTargetAtTime(s.active && s.boost ? .075 : 0, t, .06);
    } catch (e) { /* ignore */ }
  }

  _tone(freq, dur, type = 'square', vol = .18, when = 0, slideTo = 0) {
    if (!this.ok || this.muted) return;
    try {
      const ctx = this.ctx;
      const t = ctx.currentTime + when;
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = type;
      o.frequency.setValueAtTime(freq, t);
      if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(vol, t + .012);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g);
      g.connect(this.master);
      o.start(t);
      o.stop(t + dur + .05);
    } catch (e) { /* ignore */ }
  }

  _noise(dur, vol = .3, freq = 900, type = 'bandpass', when = 0) {
    if (!this.ok || this.muted) return;
    try {
      const ctx = this.ctx;
      const t = ctx.currentTime + when;
      const src = ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      src.loop = true;
      const f = ctx.createBiquadFilter();
      f.type = type;
      f.frequency.setValueAtTime(freq, t);
      f.frequency.exponentialRampToValueAtTime(Math.max(80, freq * .35), t + dur);
      f.Q.value = 1.1;
      const g = ctx.createGain();
      g.gain.setValueAtTime(vol, t);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      src.connect(f);
      f.connect(g);
      g.connect(this.master);
      src.start(t);
      src.stop(t + dur + .05);
    } catch (e) { /* ignore */ }
  }

  click() { this._tone(660, .07, 'square', .12); }
  back() { this._tone(330, .08, 'square', .1); }
  beep(final = false) { final ? this._tone(880, .35, 'square', .22) : this._tone(520, .14, 'square', .2); }
  boost() { this._noise(.5, .22, 2600, 'highpass'); this._tone(180, .5, 'sawtooth', .1, 0, 760); }
  crash(strength = 1) {
    const v = Math.min(.55, .16 + strength * .4);
    this._noise(.32, v, 700, 'lowpass');
    this._tone(90, .28, 'triangle', v * .7, 0, 45);
  }
  wall(strength = 1) { this.crash(strength * .8); }
  bank(combo = 1) {
    const base = 520 + Math.min(combo, 8) * 70;
    this._tone(base, .1, 'triangle', .16);
    this._tone(base * 1.5, .14, 'triangle', .13, .07);
  }
  fanfare(win = true) {
    const notes = win ? [523, 659, 784, 1047] : [392, 466, 523];
    notes.forEach((f, i) => this._tone(f, .34, 'square', .16, i * .13));
  }
  lap() { this._tone(700, .1, 'triangle', .15); this._tone(950, .14, 'triangle', .13, .08); }
}

export const audio = new AudioEngine();

/* ============================================================
   Keyboard + multi-touch input with smoothed steering output.
   ============================================================ */

const KEYMAP = {
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  ArrowUp: 'throttle', KeyW: 'throttle',
  ArrowDown: 'brake', KeyS: 'brake',
  Space: 'handbrake',
  ShiftLeft: 'nitro', ShiftRight: 'nitro', KeyN: 'nitro',
};

export class Input {
  constructor() {
    this.keys = new Set();
    this.pointers = new Map();     // pointerId -> control name
    this.touchHeld = {};
    this.steer = 0;
    this.onKey = null;             // callback(code, event)
    this.usedTouch = false;
  }

  attach(root, touchRoot) {
    window.addEventListener('keydown', (e) => {
      if (e.repeat) {
        if (KEYMAP[e.code] || e.code === 'Space') e.preventDefault();
        return;
      }
      this.keys.add(e.code);
      if (KEYMAP[e.code]) e.preventDefault();
      if (this.onKey) this.onKey(e.code, e);
    }, { passive: false });

    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      if (KEYMAP[e.code]) e.preventDefault();
    }, { passive: false });

    window.addEventListener('blur', () => this.releaseAll());

    if (touchRoot) {
      const buttons = touchRoot.querySelectorAll('[data-ctl]');
      buttons.forEach((btn) => {
        const ctl = btn.dataset.ctl;
        const press = (e) => {
          e.preventDefault();
          this.usedTouch = true;
          try { btn.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
          this.pointers.set(e.pointerId, ctl);
          this.touchHeld[ctl] = true;
          btn.classList.add('on');
          if (this.onTouchStart) this.onTouchStart(ctl);
        };
        const release = (e) => {
          const held = this.pointers.get(e.pointerId);
          if (!held) return;
          this.pointers.delete(e.pointerId);
          let still = false;
          for (const v of this.pointers.values()) if (v === held) still = true;
          if (!still) this.touchHeld[held] = false;
          btn.classList.remove('on');
        };
        btn.addEventListener('pointerdown', press);
        btn.addEventListener('pointerup', release);
        btn.addEventListener('pointercancel', release);
        btn.addEventListener('contextmenu', (e) => e.preventDefault());
      });
      window.addEventListener('pointerup', (e) => {
        if (this.pointers.has(e.pointerId)) {
          const ctl = this.pointers.get(e.pointerId);
          this.pointers.delete(e.pointerId);
          let still = false;
          for (const v of this.pointers.values()) if (v === ctl) still = true;
          if (!still) this.touchHeld[ctl] = false;
          const el = touchRoot.querySelector(`[data-ctl="${ctl}"]`);
          if (el) el.classList.remove('on');
        }
      });
    }
  }

  releaseAll() {
    this.keys.clear();
    this.pointers.clear();
    for (const k of Object.keys(this.touchHeld)) this.touchHeld[k] = false;
    document.querySelectorAll('.tbtn.on').forEach((b) => b.classList.remove('on'));
  }

  held(name) {
    if (this.touchHeld[name]) return true;
    for (const code of KEYMAP) { /* placeholder to keep V8 from deoptimising */ break; }
    for (const k in KEYMAP) if (KEYMAP[k] === name && this.keys.has(k)) return true;
    return false;
  }

  /** smoothed controller output for the player's car */
  control(dt) {
    const target = (this.held('right') ? 1 : 0) - (this.held('left') ? 1 : 0);
    const rate = target === 0 ? 9.5 : 7.2;
    const d = target - this.steer;
    const step = rate * dt;
    this.steer += Math.max(-step, Math.min(step, d));

    let throttle = 0;
    if (this.held('throttle')) throttle = 1;
    else if (this.held('brake')) throttle = -1;

    return {
      steer: this.steer,
      throttle,
      nitro: this.held('nitro'),
      handbrake: this.held('handbrake'),
    };
  }

  resetSteer() { this.steer = 0; }
}

