/* ============================================================
   DOM screens: menu, garage, race select, pause, results.
   ============================================================ */

import { CARS, UPGRADES, TRACKS, carSpec, EMPTY_UPGRADES } from './config.js';
import { catmullRomClosed, fmtTime, ordinal, clamp } from './utils.js';
import { makeCarSprite } from './sprites.js';
import { THEMES } from './tracks.js';

const $ = (s) => document.querySelector(s);
const $$ = (s) => Array.from(document.querySelectorAll(s));

export class UI {
  constructor(bus) {
    this.bus = bus;
    this.save = bus.save;
    this.current = 'scr-menu';
    this.selectedCar = this.save.car;
    this.selectedTrack = this.save.track;
    this.laps = this.save.laps || 3;
    this.wire();
    this.refreshCoins();
    this.buildGarage();
    this.buildTracks();
    this.updateSoundLabels();
    this.updateMenuInfo();
  }

  /* ----------------------------- plumbing ----------------------------- */
  show(id) {
    $$('.screen').forEach((s) => s.classList.toggle('active', s.id === id));
    this.current = id;
    if (id === 'scr-menu') this.updateMenuInfo();
    if (id === 'scr-garage') this.buildGarage();
    if (id === 'scr-tracks') this.buildTracks();
  }

  isVisible(id) {
    const el = document.getElementById(id);
    return !!el && el.classList.contains('active');
  }

  refreshCoins() {
    $$('[data-coins]').forEach((el) => { el.textContent = String(this.save.coins); });
  }

  updateMenuInfo() {
    const car = CARS.find((c) => c.id === this.save.car) || CARS[0];
    $('#menu-loadout').textContent = car.name;
    const best = this.save.best[this.save.track];
    $('#menu-best').textContent = best ? `BEST ${fmtTime(best)}` : 'BEST --:--.---';
    this.refreshCoins();
  }

  updateSoundLabels() {
    const txt = `Sound: ${this.save.sound ? 'On' : 'Off'}`;
    $('#btn-sound').textContent = txt;
    $('#btn-sound2').textContent = txt;
  }

  wire() {
    const b = this.bus;
    $('#btn-start').addEventListener('click', () => b.onStart());
    $('#btn-garage').addEventListener('click', () => { b.click(); this.show('scr-garage'); });
    $('#btn-races').addEventListener('click', () => { b.click(); this.show('scr-tracks'); });
    $('#btn-help').addEventListener('click', () => { b.click(); this.show('scr-help'); });
    $$('[data-back]').forEach((el) => el.addEventListener('click', () => { b.back(); this.show(el.dataset.back); }));

    $('#btn-equip').addEventListener('click', () => b.onEquip(this.selectedCar, () => { this.buildGarage(); this.updateMenuInfo(); }));
    $('#btn-start-race').addEventListener('click', () => b.onStartRace(this.selectedTrack, this.laps));
    $$('[data-laps]').forEach((el) => el.addEventListener('click', () => {
      b.click();
      this.laps = Number(el.dataset.laps);
      this.save.laps = this.laps;
      $$('[data-laps]').forEach((c) => c.classList.toggle('active', c === el));
    }));

    $('#btn-resume').addEventListener('click', () => b.onResume());
    $('#btn-restart').addEventListener('click', () => b.onRestart());
    $('#btn-quit').addEventListener('click', () => b.onQuit());
    $('#btn-sound').addEventListener('click', () => { b.onSoundToggle(); this.updateSoundLabels(); });
    $('#btn-sound2').addEventListener('click', () => { b.onSoundToggle(); this.updateSoundLabels(); });
    $('#btn-reset-save').addEventListener('click', () => b.onResetSave(() => {
      this.refreshCoins(); this.buildGarage(); this.buildTracks(); this.updateMenuInfo();
    }));

    $('#btn-again').addEventListener('click', () => b.onRestart());
    $('#btn-next').addEventListener('click', () => b.onNext());
    $('#btn-menu2').addEventListener('click', () => b.onQuit());
  }

  /* ----------------------------- garage ----------------------------- */
  buildGarage() {
    if (this.selectedCar !== this.save.car && !this.save.owned.includes(this.selectedCar)) {
      this.selectedCar = this.save.car;
    }
    const list = $('#car-list');
    list.innerHTML = '';
    for (const car of CARS) {
      const owned = this.save.owned.includes(car.id);
      const card = document.createElement('div');
      card.className = 'car-card' + (car.id === this.selectedCar ? ' active' : '') + (owned ? '' : ' locked');
      const cv = document.createElement('canvas');
      cv.width = 148;
      cv.height = 80;
      drawCarThumb(cv, car);
      const info = document.createElement('div');
      info.className = 'cc';
      info.innerHTML = `<b>${car.name}</b><span>${car.cls}</span>`;
      const right = document.createElement('div');
      if (car.id === this.save.car) {
        right.innerHTML = '<div class="equipped">IN USE</div>';
      } else if (owned) {
        right.innerHTML = '<div class="owned">OWNED</div>';
      } else {
        right.innerHTML = `<div class="price">${car.price.toLocaleString()}</div>`;
      }
      card.append(cv, info, right);
      card.addEventListener('click', () => { this.bus.click(); this.selectedCar = car.id; this.buildGarage(); });
      list.appendChild(card);
    }

    const car = CARS.find((c) => c.id === this.selectedCar) || CARS[0];
    const owned = this.save.owned.includes(car.id);
    const up = this.save.upgrades[car.id] || { ...EMPTY_UPGRADES };

    $('#car-name').textContent = car.name;
    $('#car-class').textContent = car.cls.toUpperCase();
    $('#car-desc').textContent = car.desc;
    drawCarPreview($('#car-preview'), car);

    const bonus = { engine: ['speed', .06], tires: ['grip', .07], nitro: ['speed', .015], chassis: ['handling', .06] };
    const stats = [
      ['TOP SPEED', clamp(car.stats.speed + (up.engine || 0) * .06 + (up.nitro || 0) * .012, 0, 1)],
      ['ACCELERATION', clamp(car.stats.accel + (up.engine || 0) * .07, 0, 1)],
      ['GRIP', clamp(car.stats.grip + (up.tires || 0) * .07, 0, 1)],
      ['HANDLING', clamp(car.stats.handling + (up.chassis || 0) * .06, 0, 1)],
    ];
    $('#car-stats').innerHTML = stats.map(([n, v]) =>
      `<div class="stat"><span>${n}</span><div class="bar"><i style="width:${Math.round(v * 100)}%"></i></div></div>`).join('');

    let totalLv = 0;
    const rows = Object.keys(UPGRADES).map((key) => {
      const def = UPGRADES[key];
      const lvl = up[key] || 0;
      totalLv += lvl;
      const maxed = lvl >= def.max;
      const cost = def.cost(lvl);
      const can = owned && !maxed && this.save.coins >= cost;
      const pips = Array.from({ length: def.max }, (_, i) => `<span class="pip${i < lvl ? ' on' : ''}"></span>`).join('');
      const label = !owned ? 'LOCKED' : maxed ? 'MAX' : `${cost.toLocaleString()}`;
      return `<div class="upg">
        <span class="u-name">${def.name}</span>
        <span class="pips">${pips}</span>
        <button data-upg="${key}" ${can ? '' : 'disabled'}>${label}</button>
      </div>`;
    }).join('');
    $('#car-upgrades').innerHTML = rows;
    $('#upg-count').textContent = `${totalLv}/${Object.keys(UPGRADES).length * 5}`;
    $$('#car-upgrades [data-upg]').forEach((btn) => btn.addEventListener('click', () => {
      this.bus.onUpgrade(car.id, btn.dataset.upg, () => { this.buildGarage(); this.refreshCoins(); });
    }));

    const equip = $('#btn-equip');
    if (!owned) {
      equip.textContent = `Buy for ${car.price.toLocaleString()} coins`;
      equip.disabled = this.save.coins < car.price;
    } else if (car.id === this.save.car) {
      equip.textContent = 'Selected';
      equip.disabled = true;
    } else {
      equip.textContent = 'Select Car';
      equip.disabled = false;
    }
  }

  /* ----------------------------- race select ----------------------------- */
  buildTracks() {
    const wrap = $('#track-list');
    wrap.innerHTML = '';
    for (const def of TRACKS) {
      const card = document.createElement('div');
      card.className = 'track-card' + (def.id === this.selectedTrack ? ' active' : '');
      const cv = document.createElement('canvas');
      cv.width = 440;
      cv.height = 260;
      drawTrackPreview(cv, def);
      const stars = '★'.repeat(def.difficulty) + '☆'.repeat(3 - def.difficulty);
      const best = this.save.best[def.id];
      const meta = document.createElement('div');
      meta.className = 'tc-meta';
      meta.innerHTML = `<span class="stars">${stars}</span>
        <span class="pill">${def.theme.toUpperCase()}</span>
        <span class="pill">${best ? `BEST ${fmtTime(best)}` : 'NO RECORD'}</span>`;
      const p = document.createElement('p');
      p.textContent = def.blurb;
      const h = document.createElement('h3');
      h.textContent = def.name;
      card.append(cv, h, p, meta);
      if (def.id === this.save.track) {
        const badge = document.createElement('div');
        badge.className = 'badge';
        badge.textContent = 'SELECTED';
        card.appendChild(badge);
      }
      card.addEventListener('click', () => {
        this.bus.click();
        this.selectedTrack = def.id;
        this.save.track = def.id;
        this.buildTracks();
      });
      wrap.appendChild(card);
    }
    $$('[data-laps]').forEach((c) => c.classList.toggle('active', Number(c.dataset.laps) === this.laps));
  }

  /* ----------------------------- pause / results ----------------------------- */
  openPause(stats) {
    $('#pause-stats').innerHTML = stats;
    this.show('scr-pause');
  }

  fillResults(res, coins, isRecord) {
    $('#res-pos').textContent = ordinal(res.pos);
    $('#res-track').textContent = TRACKS.find((t) => t.id === res.trackId).name;
    $('#res-headline').textContent =
      res.pos === 1 ? 'VICTORY!' : res.pos <= 3 ? 'PODIUM FINISH' : 'FINISH!';
    $('#res-total').textContent = fmtTime(res.total);
    $('#res-best').textContent = res.best ? fmtTime(res.best) : '--:--.---';
    $('#res-drift').textContent = res.drift.toLocaleString();
    $('#res-coins').textContent = `+${coins.toLocaleString()}`;
    $('#res-table').innerHTML =
      `<tr><th>POS</th><th>DRIVER</th><th>CAR</th><th>TIME</th></tr>` +
      res.rows.map((r) => `<tr class="${r.isPlayer ? 'me' : ''}">
        <td class="pos">${r.pos}</td>
        <td>${r.name}</td>
        <td>${r.car}</td>
        <td>${r.time ? fmtTime(r.time) : `L${r.laps} · DNF`}</td>
      </tr>`).join('');
    const rec = document.createElement('div');
    rec.className = 'pill';
    rec.style.cssText = 'align-self:center';
    rec.innerHTML = isRecord ? '&#127942; NEW LAP RECORD' : `&nbsp;`;
    const old = $('#scr-results .pill.dyn');
    if (old) old.remove();
    rec.classList.add('dyn');
    rec.style.opacity = isRecord ? '1' : '0';
    $('#scr-results .res-actions').before(rec);
    this.show('scr-results');
  }
}

/* ----------------------------- drawing helpers ----------------------------- */
function drawCarThumb(cv, car) {
  const x = cv.getContext('2d');
  const spr = makeCarSprite(car.shape, { body: car.body, body2: car.body2, accent: car.accent }, car.glass, 4);
  x.clearRect(0, 0, cv.width, cv.height);
  x.save();
  const s = Math.min((cv.width - 16) / spr.w, (cv.height - 14) / spr.h);
  x.translate(cv.width / 2, cv.height / 2);
  x.scale(s, s);
  x.drawImage(spr.canvas, -spr.w / 2, -spr.h / 2, spr.w, spr.h);
  x.restore();
}

function drawCarPreview(cv, car) {
  const x = cv.getContext('2d');
  const w = cv.width;
  const h = cv.height;
  x.clearRect(0, 0, w, h);
  const g = x.createRadialGradient(w / 2, h * 0.4, 20, w / 2, h / 2, w * 0.55);
  g.addColorStop(0, 'rgba(255,255,255,.10)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = g;
  x.fillRect(0, 0, w, h);

  // floor grid
  x.strokeStyle = 'rgba(255,255,255,.05)';
  x.lineWidth = 1;
  for (let i = 0; i < 14; i++) {
    x.beginPath();
    x.moveTo((i / 14) * w, h * 0.62);
    x.lineTo((i / 14) * w - 30, h);
    x.stroke();
  }
  x.beginPath();
  x.moveTo(0, h * 0.66);
  x.lineTo(w, h * 0.66);
  x.stroke();

  const spr = makeCarSprite(car.shape, { body: car.body, body2: car.body2, accent: car.accent }, car.glass, 5);
  const s = Math.min((w - 60) / spr.w, (h - 50) / spr.h);
  x.save();
  x.translate(w / 2, h / 2 + 8);
  x.scale(s, s);
  x.fillStyle = 'rgba(0,0,0,.55)';
  x.beginPath();
  x.ellipse(6, 14, spr.w * 0.5, spr.h * 0.4, 0, 0, Math.PI * 2);
  x.fill();
  x.drawImage(spr.canvas, -spr.w / 2, -spr.h / 2, spr.w, spr.h);
  x.restore();

  x.font = `900 italic 26px "Arial Narrow", Impact, sans-serif`;
  x.textAlign = 'left';
  x.fillStyle = 'rgba(255,255,255,.16)';
  x.fillText(car.name, 16, h - 18);
}

function drawTrackPreview(cv, def) {
  const x = cv.getContext('2d');
  const w = cv.width;
  const h = cv.height;
  const theme = THEMES[def.theme];
  x.fillStyle = theme.ground;
  x.fillRect(0, 0, w, h);

  // texture
  for (let i = 0; i < 240; i++) {
    x.globalAlpha = 0.12 + Math.random() * 0.2;
    x.fillStyle = theme.speck[(Math.random() * theme.speck.length) | 0];
    x.fillRect(Math.random() * w, Math.random() * h, 3, 3);
  }
  x.globalAlpha = 1;

  const pts = catmullRomClosed(def.points, 14);
  let minX = 1e9, minY = 1e9, maxX = -1e9, maxY = -1e9;
  for (const p of pts) {
    minX = Math.min(minX, p[0]); maxX = Math.max(maxX, p[0]);
    minY = Math.min(minY, p[1]); maxY = Math.max(maxY, p[1]);
  }
  const pad = 34;
  const sc = Math.min((w - pad * 2) / (maxX - minX), (h - pad * 2) / (maxY - minY));
  const ox = (w - (maxX - minX) * sc) / 2 - minX * sc;
  const oy = (h - (maxY - minY) * sc) / 2 - minY * sc;

  x.save();
  x.translate(ox, oy);
  x.scale(sc, sc);
  const path = new Path2D();
  pts.forEach((p, i) => (i ? path.lineTo(p[0], p[1]) : path.moveTo(p[0], p[1])));
  path.closePath();

  x.lineJoin = 'round';
  x.lineCap = 'round';
  x.strokeStyle = 'rgba(0,0,0,.5)';
  x.lineWidth = 96;
  x.stroke(path);
  x.strokeStyle = theme.asphalt;
  x.lineWidth = 84;
  x.stroke(path);
  x.strokeStyle = 'rgba(255,255,255,.28)';
  x.lineWidth = 66;
  x.setLineDash([22, 30]);
  x.stroke(path);
  x.setLineDash([]);

  const s0 = pts[0];
  const s1 = pts[1];
  const a = Math.atan2(s1[1] - s0[1], s1[0] - s0[0]);
  x.save();
  x.translate(s0[0], s0[1]);
  x.rotate(a);
  x.fillStyle = '#fff';
  for (let r = 0; r < 2; r++) {
    for (let c = -4; c < 4; c++) {
      if ((r + c) & 1) continue;
      x.fillRect(r * 16 - 8, c * 16, 16, 16);
    }
  }
  x.restore();
  x.restore();

  // corner label
  x.font = `900 italic 30px "Arial Narrow", Impact, sans-serif`;
  x.textAlign = 'right';
  x.fillStyle = 'rgba(0,0,0,.55)';
  x.fillText(def.name, w - 14, h - 14);
}

/* ============================================================
   DRIFT LEGENDS — boot, state machine and fixed-step loop.
   ============================================================ */

import {
  loadSave, persistSave, defaultSave, SAVE_KEY,
  CARS, TRACKS, AI_ROSTER, EMPTY_UPGRADES, UPGRADES,
} from './config.js';
import { buildTrack, renderTrackLayer } from './tracks.js';
import { Renderer } from './renderer.js';
import { Input } from './input.js';
import { Race } from './race.js';
import { effects } from './effects.js';
import { audio } from './audio.js';
import { UI } from './ui.js';
import { clamp, isTouchLike, ordinal } from './utils.js';

const STEP = 1 / 120;
const canvas = document.getElementById('game');
const save = loadSave();
const renderer = new Renderer(canvas);
const input = new Input();

let state = 'boot';
let race = null;
let currentTrack = null;
let acc = 0;
let last = 0;
let finishHandled = false;
let frameCount = 0;
let perfAcc = 0;
let perfTier = 0;
let touchMode = false;

const hud = {
  root: document.getElementById('hud'),
  countdown: document.getElementById('countdown'),
  banner: document.getElementById('banner'),
  wrongway: document.getElementById('wrongway'),
  driftbox: document.getElementById('driftbox'),
  driftNum: document.getElementById('drift-num'),
  touch: document.getElementById('touch'),
  pause: document.getElementById('btn-pause'),
};
let lastCombo = 1;
let lastCountdown = '';

/* ------------------------------------------------------------ helpers */
function shade(hex, f) {
  const n = parseInt(hex.slice(1), 16);
  const r = clamp(Math.round(((n >> 16) & 255) * f), 0, 255);
  const g = clamp(Math.round(((n >> 8) & 255) * f), 0, 255);
  const b = clamp(Math.round((n & 255) * f), 0, 255);
  return `#${((r << 16) | (g << 8) | b).toString(16).padStart(6, '0')}`;
}

function ensureTrack(id) {
  const def = TRACKS.find((t) => t.id === id) || TRACKS[0];
  if (currentTrack && currentTrack.def.id === def.id) return currentTrack;
  const t = buildTrack(def);
  renderTrackLayer(t);
  currentTrack = t;
  renderer.setTrack(t);
  return t;
}

function makeEntries(demo) {
  const playerCar = CARS.find((c) => c.id === save.car) || CARS[0];
  const models = CARS.filter((c) => c.id !== playerCar.id);
  const roster = AI_ROSTER.slice(0, 5).sort((a, b) => b.skill - a.skill);
  const entries = roster.map((d, i) => {
    const model = models[i % models.length];
    return {
      carDef: model,
      colors: { body: d.skin, body2: shade(d.skin, 0.45), accent: shade(d.skin, 1.6), glass: model.glass },
      mapColor: d.skin,
      name: d.name,
      skill: d.skill,
      isPlayer: false,
    };
  });
  entries.push({
    carDef: playerCar,
    colors: { body: playerCar.body, body2: playerCar.body2, accent: playerCar.accent, glass: playerCar.glass },
    mapColor: '#ffffff',
    name: demo ? 'FAN' : 'YOU',
    isPlayer: !demo,
    upgrades: save.upgrades[playerCar.id] || { ...EMPTY_UPGRADES },
  });
  return entries;
}

/* ------------------------------------------------------------ state */
function setState(next) {
  state = next;
  const racing = next === 'race';
  hud.root.classList.toggle('hidden', !(next === 'race' || next === 'paused'));
  hud.touch.classList.toggle('hidden', !(racing && touchMode));
  if (next === 'menu') {
    ui.show('scr-menu');
  } else if (next !== 'paused') {
    ui.show('');
  }
}

function startDemo() {
  const track = ensureTrack(save.track);
  effects.reset();
  race = new Race({
    track,
    entries: makeEntries(true),
    laps: 3,
    mode: 'demo',
    playerIndex: Math.min(1, 4),
  });
  renderer.cam.init = false;
  finishHandled = false;
}

function startRace(trackId, laps) {
  audio.resume();
  const track = ensureTrack(trackId || save.track);
  const entries = makeEntries(false);
  effects.reset();
  input.resetSteer();
  race = new Race({
    track,
    entries,
    laps: laps || save.laps || 3,
    mode: 'race',
    playerIndex: entries.length - 1,
  });
  renderer.cam.init = false;
  finishHandled = false;
  lastCombo = 1;
  lastCountdown = '';
  setState('race');
}

function togglePause(force) {
  if (state === 'race') {
    const h = race.hudFor(race.player);
    ui.openPause(
      `<span>${race.track.def.name}</span><span>LAP ${h.lap}/${race.laps}</span><span>POS ${ordinal(h.place)}</span>`
    );
    setState('paused');
    input.releaseAll();
    audio.back();
  } else if (state === 'paused' && force !== false) {
    ui.show('');
    setState('race');
    audio.click();
  }
}

function finishRace() {
  if (finishHandled) return;
  finishHandled = true;
  const res = race.buildResult();
  const def = TRACKS.find((t) => t.id === res.trackId);
  const prevBest = save.best[res.trackId];
  const isRecord = !!res.best && (!prevBest || res.best < prevBest);
  if (isRecord) save.best[res.trackId] = res.best;

  const posBonus = [650, 450, 320, 240, 190, 150][res.pos - 1] || 130;
  const lapBonus = res.lapsCount * 70;
  const driftBonus = Math.round(res.drift / 12);
  const diffMult = 1 + (def.difficulty - 1) * 0.15;
  const earned = Math.round((posBonus + lapBonus + driftBonus) * diffMult);

  save.coins += earned;
  save.races = (save.races || 0) + 1;
  if (res.pos === 1) save.wins = (save.wins || 0) + 1;
  persistSave(save);

  hud.root.classList.add('hidden');
  hud.touch.classList.add('hidden');
  setState('results');
  ui.fillResults(res, earned, isRecord);
}

function quitToMenu() {
  persistSave(save);
  startDemo();
  setState('menu');
}

/* ------------------------------------------------------------ UI bus */
const ui = new UI({
  save,
  click: () => audio.click(),
  back: () => audio.back(),
  onStart: () => startRace(save.track, save.laps),
  onStartRace: (trackId, laps) => {
    save.track = trackId;
    save.laps = laps;
    persistSave(save);
    startRace(trackId, laps);
  },
  onEquip: (id, cb) => {
    const car = CARS.find((c) => c.id === id);
    if (!car) return;
    if (!save.owned.includes(id)) {
      if (save.coins < car.price) { audio.back(); return; }
      save.coins -= car.price;
      save.owned.push(id);
      save.upgrades[id] = save.upgrades[id] || { ...EMPTY_UPGRADES };
      audio.bank(3);
    } else {
      audio.click();
    }
    save.car = id;
    persistSave(save);
    cb && cb();
  },
  onUpgrade: (carId, key, cb) => {
    const def = UPGRADES[key];
    save.upgrades[carId] = save.upgrades[carId] || { ...EMPTY_UPGRADES };
    const lvl = save.upgrades[carId][key] || 0;
    if (lvl >= def.max) { audio.back(); return; }
    const cost = def.cost(lvl);
    if (save.coins < cost) { audio.back(); return; }
    save.coins -= cost;
    save.upgrades[carId][key] = lvl + 1;
    persistSave(save);
    audio.bank(2);
    cb && cb();
  },
  onResume: () => togglePause(true),
  onRestart: () => startRace(race ? race.track.def.id : save.track, race ? race.laps : save.laps),
  onQuit: () => { audio.click(); quitToMenu(); },
  onSoundToggle: () => {
    save.sound = !save.sound;
    audio.setMuted(!save.sound);
    persistSave(save);
    if (save.sound) audio.click();
  },
  onResetSave: (cb) => {
    const fresh = defaultSave();
    Object.keys(fresh).forEach((k) => { save[k] = fresh[k]; });
    try { localStorage.removeItem(SAVE_KEY); } catch (e) { /* ignore */ }
    persistSave(save);
    audio.click();
    cb && cb();
  },
});

/* ------------------------------------------------------------ input */
input.onKey = (code) => {
  audio.resume();
  if (code === 'Escape' || code === 'KeyP') {
    if (state === 'race' || state === 'paused') togglePause();
  } else if (code === 'KeyR') {
    if (state === 'race' && race && race.mode !== 'demo') race.recoverCar(race.player);
  } else if (code === 'Enter') {
    if (state === 'menu') startRace(save.track, save.laps);
    else if (state === 'paused') togglePause(true);
  } else if (code === 'KeyM') {
    save.sound = !save.sound;
    audio.setMuted(!save.sound);
    ui.updateSoundLabels();
    persistSave(save);
  }
};
input.attach(window, hud.touch);
hud.pause.addEventListener('click', () => { audio.resume(); togglePause(); });

window.addEventListener('pointerdown', () => audio.resume(), { passive: true });
window.addEventListener('keydown', () => audio.resume(), { passive: true });
window.addEventListener('resize', () => { renderer.resize(); touchMode = isTouchLike(); });
document.addEventListener('visibilitychange', () => {
  if (document.hidden && state === 'race') togglePause();
});

/* ------------------------------------------------------------ DOM hud */
function updateDOMHUD() {
  if (state !== 'race' || !race) return;

  if (race.mode === 'countdown') {
    const n = Math.max(1, Math.ceil(race.countdown));
    const s = String(n);
    if (s !== lastCountdown) { lastCountdown = s; hud.countdown.textContent = s; }
    hud.countdown.classList.remove('hidden', 'go');
  } else if (race.goTimer > 0) {
    if (lastCountdown !== 'GO') { lastCountdown = 'GO'; hud.countdown.textContent = 'GO!'; }
    hud.countdown.classList.add('go');
    hud.countdown.classList.remove('hidden');
  } else {
    hud.countdown.classList.add('hidden');
  }

  if (race.banner) {
    hud.banner.textContent = race.banner;
    hud.banner.classList.remove('hidden');
  } else {
    hud.banner.classList.add('hidden');
  }

  hud.wrongway.classList.toggle('hidden', !race.wrongWay);

  const h = race.hudFor(race.player);
  if (h.drifting && h.chain > 50) {
    hud.driftbox.classList.remove('hidden');
    if (h.combo !== lastCombo) {
      lastCombo = h.combo;
      hud.driftbox.classList.remove('pop');
      void hud.driftbox.offsetWidth;
      hud.driftbox.classList.add('pop');
    }
    hud.driftNum.textContent = `${h.chain}${h.combo > 1 ? '  x' + h.combo : ''}`;
  } else {
    hud.driftbox.classList.add('hidden');
    if (!h.drifting) lastCombo = 1;
  }
}

/* ------------------------------------------------------------ loop */
function fixedUpdate(dt) {
  if (!race) return;
  if (state === 'race') {
    race.update(dt, input.control(dt));
    effects.update(dt);
    if (race.mode !== 'demo' && race.phase === 'finished') finishRace();
  } else if (state === 'menu' || state === 'boot') {
    race.update(dt, null);
    effects.update(dt);
  }
}

function render(dt) {
  if (!race) return;
  const target = state === 'menu' || state === 'boot'
    ? race.cars[Math.min(1, race.cars.length - 1)]
    : race.player;
  renderer.frameCamera(target, dt, race);
  renderer.drawWorld(race, dt);
  renderer.drawHUD(race, { touch: touchMode, best: save.best[race.track.def.id] });
}

function frame(now) {
  requestAnimationFrame(frame);
  if (!last) last = now;
  let dt = (now - last) / 1000;
  last = now;
  if (dt > 0.1) dt = 0.1;
  if (dt <= 0) dt = 1 / 60;

  acc += dt;
  let steps = 0;
  while (acc >= STEP && steps < 10) { fixedUpdate(STEP); acc -= STEP; steps++; }
  if (steps === 10) acc = 0;

  render(dt);
  updateDOMHUD();

  // audio mix follows the rendered frame
  if (race && (state === 'race' || state === 'menu')) {
    const c = race.player;
    const slip = Math.abs(c.slip);
    audio.mix({
      active: save.sound,
      speed: c.speed,
      throttle: Math.max(0, c.throttleVis),
      skid: clamp((slip - 0.08) * 2.4, 0, 1) * clamp(c.speed / 240, 0, 1),
      boost: c.boosting,
    });
  } else {
    audio.mix({ active: false, speed: 0, throttle: 0, skid: 0, boost: false });
  }

  // adaptive quality: dial effects back if the machine is struggling
  frameCount++;
  perfAcc += dt;
  if (frameCount === 150) {
    const avg = perfAcc / frameCount;
    if (avg > 0.026 && perfTier === 0) {
      perfTier = 1;
      effects.quality = 0.55;
      renderer.dprCap = 1;
      renderer.resize();
    } else if (avg > 0.034 && perfTier === 1) {
      perfTier = 2;
      effects.quality = 0.3;
    }
    frameCount = 0;
    perfAcc = 0;
  }
}

/* ------------------------------------------------------------ boot */
function boot() {
  touchMode = isTouchLike();
  audio.setMuted(!save.sound);
  audio.init();

  // build the default circuit right away so the first click is instant
  ensureTrack(save.track);
  startDemo();
  setState('menu');
  ui.show('scr-menu');

  const loading = document.getElementById('loading');
  loading.classList.add('done');
  setTimeout(() => { loading.style.display = 'none'; }, 700);

  last = 0;
  requestAnimationFrame(frame);
}

// Give the browser a painted frame first, then boot the engine.
requestAnimationFrame(() => requestAnimationFrame(boot));

// expose a tiny hook for automated smoke tests
window.__driftLegends = {
  get state() { return state; },
  get race() { return race; },
  start: (trackId, laps) => startRace(trackId, laps),
  pause: () => togglePause(),
};

