  ctx.translate(px, py);
  ctx.scale(sc, sc);
  ctx.translate(-b.minX, -b.minY);

  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  ctx.strokeStyle = 'rgba(4,7,12,.82)';
  ctx.lineWidth = PHYS.roadHalf * 2.4;
