import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(require('fs').readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + require('fs').readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.log('PAGEERROR:', e.message))
await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
await page.locator('body').waitFor({ state: 'visible' })
await page.waitForFunction(() => document.fonts.status === 'loaded')

const t0 = Date.now()
// poll the button's actionability the way capture-start does
const probe = async () => page.evaluate(() => {
  const b = document.getElementById('btn-start')
  const loading = document.getElementById('loading')
  const r = b.getBoundingClientRect()
  const el = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2)
  return {
    visible: !!r.width,
    cover: el ? `${el.tagName}#${el.id}` : null,
    loadingClass: loading.className,
    loadingPE: getComputedStyle(loading).pointerEvents,
    menuShown: !document.getElementById('scr-menu').classList.contains('hidden'),
  }
})
for (let i = 0; i < 12; i++) {
  console.log(Date.now() - t0, 'ms', JSON.stringify(await probe()))
  await page.waitForTimeout(250)
}
const start = Date.now()
try {
  const btn = page.locator('#btn-start')
  await btn.click({ trial: true, timeout: 3000 })
  console.log('TRIAL OK after', Date.now() - start, 'ms')
  await btn.click({ timeout: 2000, noWaitAfter: true })
  console.log('CLICKED OK')
} catch (e) {
  console.log('TRIAL FAIL:', e.name, e.message.slice(0, 200))
}
await browser.close()

