import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const fs = require('fs')
const config = JSON.parse(fs.readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + fs.readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.log('PAGEERROR:', e.message))
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERR:', m.text()) })
await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
await page.locator('body').waitFor({ state: 'visible' })
await page.waitForFunction(() => document.fonts.status === 'loaded')

// sample the rect every frame for 3s
const changes = await page.evaluate(() => new Promise(resolve => {
  const b = document.getElementById('btn-start')
  let last = null, diffs = 0, frames = 0
  const t0 = performance.now()
  const tick = () => {
    const r = b.getBoundingClientRect()
    const key = `${Math.round(r.x)},${Math.round(r.y)},${Math.round(r.width)},${Math.round(r.height)}`
    if (last && key !== last) { diffs++; if (diffs <= 8) console.log('rect change', last, '->', key) }
    last = key
    frames++
    if (performance.now() - t0 < 3000) requestAnimationFrame(tick)
    else resolve({ frames, diffs, lastRect: last, fonts: document.fonts.status })
  }
  requestAnimationFrame(tick)
}))
console.log(JSON.stringify(changes))

// now try the exact capture flow
const candidate = page.locator('button, input[type="button"], input[type="submit"], [role="button"]')
const matches = []
for (const control of await candidate.all()) {
  if (!await control.isVisible() || !await control.isEnabled()) continue
  const eligible = await control.evaluate((element) => {
    if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false
    const label = element.getAttribute('aria-label') || element.value || element.textContent || ''
    return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())
  })
  if (eligible) matches.push(control)
}
console.log('matches:', matches.length)
const start = Date.now()
try {
  await matches[0].click({ trial: true, timeout: 3000 })
  console.log('TRIAL OK in', Date.now() - start)
  await matches[0].click({ timeout: 2000, noWaitAfter: true })
  console.log('CLICKED')
} catch (e) {
  console.log('FAIL', e.name, e.message.slice(0, 300))
}
await browser.close()

