import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const fs = require('fs')
const config = JSON.parse(fs.readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + fs.readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.log('PAGEERROR:', e.message))
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERR:', m.text().slice(0, 200)) })

// inject longtask + rect observer before any script runs
await page.addInitScript(() => {
  window.__log = []
  const t0 = performance.now()
  try {
    new PerformanceObserver(l => { for (const e of l.getEntries()) window.__log.push(`LONGTASK ${Math.round(e.startTime)}+${Math.round(e.duration)}`) }).observe({ entryTypes: ['longtask'] })
  } catch {}
  const tick = () => {
    const b = document.getElementById('btn-start')
    if (b) {
      const r = b.getBoundingClientRect()
      const load = document.getElementById('loading')
      window.__log.push(`t${Math.round(performance.now())} rect ${Math.round(r.x)},${Math.round(r.y)},${Math.round(r.width)},${Math.round(r.height)} cover=${load && getComputedStyle(load).display !== 'none' ? 'loading' : 'ok'}`)
    }
    requestAnimationFrame(tick)
  }
  requestAnimationFrame(tick)
  void t0
})

await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
await page.locator('body').waitFor({ state: 'visible' })
await page.waitForFunction(() => document.fonts.status === 'loaded')

const start = Date.now()
try {
  const btn = page.locator('#btn-start')
  await btn.click({ trial: true, timeout: 2000 })
  console.log('TRIAL OK in', Date.now() - start, 'ms')
  await btn.click({ timeout: 2000, noWaitAfter: true })
  console.log('CLICKED')
} catch (e) {
  console.log('FAIL', e.name, 'after', Date.now() - start, 'ms')
}
const log = await page.evaluate(() => window.__log)
// condense: show rect changes and longtasks only
let last = null
for (const line of log) {
  if (line.startsWith('LONGTASK')) { console.log(line); continue }
  if (line !== last) { console.log(line); last = line }
}
await browser.close()

