import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const fs = require('fs')
const config = JSON.parse(fs.readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + fs.readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
for (let run = 1; run <= 3; run++) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  page.on('pageerror', e => console.log('PAGEERROR:', e.message))
  const t0 = Date.now()
  await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
  const tLoad = Date.now() - t0
  // how long until the splash is dismissed (boot finished)?
  let tBoot = -1
  try {
    await page.waitForFunction(() => {
      const l = document.getElementById('loading')
      return l && (l.classList.contains('done') || getComputedStyle(l).display === 'none')
    }, { timeout: 20000 })
    tBoot = Date.now() - t0
  } catch { console.log(`run${run}: boot never finished within 20s`) }
  // how long until rAF produces 10 frames?
  const tFrames = await page.evaluate(() => new Promise(res => {
    let n = 0; const s = performance.now()
    const tick = () => { if (++n >= 10) res(Math.round(performance.now() - s)); else requestAnimationFrame(tick) }
    requestAnimationFrame(tick)
  })).catch(() => 'timeout')
  console.log(`run${run}: load=${tLoad}ms bootDone=${tBoot}ms 10frames=${tFrames}ms`)
  await page.close()
}
await browser.close()

