const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const fs = require('fs')
const config = JSON.parse(fs.readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + fs.readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.log('PAGEERROR:', e.message))
await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
await page.locator('body').waitFor({ state: 'visible' })
await page.waitForFunction(() => document.fonts.status === 'loaded')

// time the actual heavy work the deferred callback does
const res = await page.evaluate(async () => {
  const t = {}
  let s = performance.now()
  const { buildTrack, renderTrackLayer } = await import('./js/tracks.js')
  t.import = +(performance.now() - s).toFixed(1)
  s = performance.now()
  const tr = buildTrack({ id: 'harbor', name: 'SUNSET HARBOR', theme: 'harbor', laps: 3, difficulty: 2 })
  t.build = +(performance.now() - s).toFixed(1)
  s = performance.now()
  renderTrackLayer(tr)
  t.layer = +(performance.now() - s).toFixed(1)
  s = performance.now()
  // force the first upload by drawing it once into the visible canvas
  const c = document.getElementById('game')
  const ctx = c.getContext('2d')
  ctx.drawImage(tr.layer.canvas, 0, 0, 400, 300, 0, 0, 400, 300)
  ctx.getImageData(0, 0, 8, 8)
  t.firstUpload = +(performance.now() - s).toFixed(1)
  t.layerSize = tr.layer.w + 'x' + tr.layer.h
  return t
})
console.log(JSON.stringify(res))
await browser.close()

